import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.hw3Av5Vn.js";const r="/llamatron/assets/arrange.CdUdvjHj.svg",c="/llamatron/assets/arrange_details.kYA5PI32.svg",s="/llamatron/assets/arrange_details_locked.FpKVQiIK.svg",n="/llamatron/assets/scene_view.D7yYfLmP.svg",i="/llamatron/assets/scene_view_played.DJiZIXpG.svg",b=JSON.parse('{"title":"Arrange","description":"","frontmatter":{},"headers":[],"relativePath":"ARRANGE.md","filePath":"ARRANGE.md"}'),h={name:"ARRANGE.md"};function l(p,e,m,g,k,w){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="arrange" tabindex="-1">Arrange <a class="header-anchor" href="#arrange" aria-label="Permalink to &quot;Arrange&quot;">​</a></h1><p>Arrange is where a song is put together: scenes as rows, tracks as columns, and a clip where a row and a column meet. This page covers the Arrange page itself. <a href="./TRACKS">Tracks</a>, <a href="./SCENES">Scenes</a> and <a href="./CLIPS">Clips</a> cover the settings of each, and <a href="./PLAYING_LIVE">Playing Live</a> covers playing the song.</p><p><img src="'+r+'" alt="The Arrange page, showing the clip grid of minimal_techno"></p><h2 id="grid-layout" tabindex="-1">Grid Layout <a class="header-anchor" href="#grid-layout" aria-label="Permalink to &quot;Grid Layout&quot;">​</a></h2><p>Press <code>A</code> on the main screen to open the current song&#39;s arrangement. The track names run across the top, and the first column holds the scene names, each with its repeat count and length. Scenes play from top to bottom. A new song starts with <code>track 1</code> and <code>scene 1</code>, and new tracks and scenes are numbered the same way until they are renamed on their own pages.</p><p>A double-lined box marks whatever the cursor is on: a clip, a scene, a track name, or one of the <code>+</code> places, including the <code>+</code> after the last track. The arrows move the box around the grid. When there are more tracks or scenes than fit, the clips scroll while the track names and the scene column stay in place. An empty cell is blank until the cursor reaches it, when it shows <code>+</code> and <code>add</code>.</p><p>Under each scene is a bar of its length against the longest scene&#39;s, and under each clip a bar of the clip&#39;s length against its scene&#39;s. A clip that fills its scene, or loops, has a full bar, and a clip that ends early has a shorter one.</p><h2 id="keys" tabindex="-1">Keys <a class="header-anchor" href="#keys" aria-label="Permalink to &quot;Keys&quot;">​</a></h2><p>The keys depend on what is under the cursor:</p><table tabindex="0"><thead><tr><th>Where</th><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td>A track&#39;s name</td><td><code>Enter</code></td><td>Open the track editor, as <a href="./TRACKS">Tracks</a> describes</td></tr><tr><td>A track&#39;s name</td><td><code>I</code></td><td>Insert a blank track before it</td></tr><tr><td>A track&#39;s name</td><td><code>C</code></td><td>Copy the track and its clips to its right</td></tr><tr><td>A track&#39;s name</td><td><code>M</code></td><td>Pick the track up: <code>←→</code> carry it, and <code>Enter</code> drops it</td></tr><tr><td>A track&#39;s name</td><td><code>Bksp</code></td><td>Delete the track and its clips, after asking; the last track can&#39;t be deleted</td></tr><tr><td>The <code>+</code> after the last track, or any track&#39;s name</td><td><code>Enter</code> or <code>A</code></td><td>Add a track at the end</td></tr><tr><td>A scene&#39;s name</td><td><code>Enter</code></td><td>Open the Scene page, as <a href="./SCENES">Scenes</a> describes</td></tr><tr><td>A scene&#39;s row</td><td><code>I</code></td><td>Insert a blank scene above it</td></tr><tr><td>A scene&#39;s row</td><td><code>C</code></td><td>Copy the scene and all its clips below it</td></tr><tr><td>A scene&#39;s name</td><td><code>M</code></td><td>Pick the scene up: <code>↑↓</code> carry it, and <code>Enter</code> drops it</td></tr><tr><td>A clip</td><td><code>M</code></td><td>Pick the clip up: the arrows carry it to the nearest empty cell, and <code>Enter</code> drops it</td></tr><tr><td>A scene&#39;s name</td><td><code>Bksp</code></td><td>Delete the scene and its clips, after asking; the last scene can&#39;t be deleted</td></tr><tr><td>A scene&#39;s row</td><td><code>A</code></td><td>Add a scene below it</td></tr><tr><td>The <code>+</code> row at the bottom</td><td><code>Enter</code> or <code>A</code></td><td>Add a scene at the end</td></tr><tr><td>An empty cell</td><td><code>Enter</code></td><td>Choose a pattern and add a clip; <code>Enter</code> on the clip again opens it</td></tr><tr><td>An empty cell</td><td><code>B</code></td><td>Make a blank pattern named after the track, add a clip of it and open it in the pattern editor</td></tr><tr><td>A clip</td><td><code>Enter</code></td><td>Open the clip page, as <a href="./CLIPS">Clips</a> describes</td></tr><tr><td>A clip</td><td><code>J</code></td><td>Jump to the clip&#39;s pattern in the pattern editor; <code>Esc</code> comes back to the clip</td></tr><tr><td>A clip</td><td><code>C</code></td><td>Copy the clip</td></tr><tr><td>A clip</td><td><code>Bksp</code></td><td>Delete the clip, after asking</td></tr><tr><td>A cell, after copying a clip</td><td><code>V</code></td><td>Paste the copied clip here, replacing what&#39;s there</td></tr><tr><td>The corner over the scene names</td><td><code>Space</code></td><td>Play the song from the top, or stop everything, with Real Time on</td></tr><tr><td>A scene&#39;s name</td><td><code>Space</code></td><td>Play the song from this scene, or stop everything, with Real Time on</td></tr><tr><td>A clip</td><td><code>Space</code></td><td>Play this clip on its own, or stop its track, with Real Time on</td></tr><tr><td>Anywhere</td><td><code>D</code></td><td>Show or hide the details of every cell (see Details View below)</td></tr><tr><td>A track&#39;s name, a scene&#39;s name or a clip</td><td><code>Tab</code></td><td>Lock into its details to pick, open, add or remove chains and open other settings (see Details View below)</td></tr><tr><td>A scene&#39;s name</td><td><code>P</code></td><td>Open Scene View, the scene&#39;s notes laid out by track (see Scene View below)</td></tr></tbody></table><h2 id="clip-marks" tabindex="-1">Clip Marks <a class="header-anchor" href="#clip-marks" aria-label="Permalink to &quot;Clip Marks&quot;">​</a></h2><p>Marks after a clip&#39;s pattern name show its settings:</p><table tabindex="0"><thead><tr><th>Mark</th><th>Meaning</th></tr></thead><tbody><tr><td><code>×3</code></td><td>Repeats 3 times</td></tr><tr><td><code>∞</code></td><td>Loops</td></tr><tr><td><code>~</code></td><td>Morphs to another pattern</td></tr><tr><td><code>d</code></td><td>Has its own play direction</td></tr><tr><td><code>g</code></td><td>Grabs notes from another track</td></tr></tbody></table><h2 id="details-view" tabindex="-1">Details View <a class="header-anchor" href="#details-view" aria-label="Permalink to &quot;Details View&quot;">​</a></h2><p><code>D</code> shows the details view, which reveals how a song is put together, and <code>D</code> again goes back to the usual grid. Under each scene&#39;s bar, each clip&#39;s bar and each track&#39;s name are the chains it runs, in the order they run, each written <code>chain: name</code>, then a <code>+</code> for adding another, then each setting that isn&#39;t its default, on a line of its own, such as <code>scale:</code> for a scale other than the song&#39;s, <code>morph: other</code>, <code>direction: pendulum</code>, <code>density: 25→100</code> or <code>inst: piano</code>. A cell with nothing of its own says <code>stock</code>. Columns widen to fit, and blue dividers separate the tracks. Every key works as it does in the usual grid.</p><p><img src="'+c+'" alt="Arrange&#39;s details view of mainstreet_hoedown, showing each clip&#39;s chains"></p><p>The details are also where a cell&#39;s chains are edited. With the cursor on a track&#39;s name, a scene&#39;s name or a clip, <code>Tab</code> locks into that cell&#39;s details. This works in the usual grid too, where it opens that one cell&#39;s details. The cell&#39;s box turns green and the first line that names something is picked, shown in brackets. <code>↑↓</code> choose a line. <code>Enter</code> on a chain, a scale, an instrument or a groove opens its page, and <code>Esc</code> comes back to the locked cell. <code>Enter</code> on <code>+</code> offers the set&#39;s chains and adds the one chosen to this cell alone. <code>Bksp</code> on a <code>chain:</code> line takes that chain out of this cell alone; the chain itself stays in the set and in every other cell that runs it. <code>Tab</code> again or <code>Esc</code> leaves the cell, and <code>D</code> leaves it and closes every detail.</p><p><img src="'+s+'" alt="Locked into a clip&#39;s details, its chain picked"></p><h2 id="scene-view" tabindex="-1">Scene View <a class="header-anchor" href="#scene-view" aria-label="Permalink to &quot;Scene View&quot;">​</a></h2><p><code>P</code> on a scene&#39;s name opens Scene View, a window over Arrange that lays out every note the scene plays, track by track, on one piano roll: each track in a colour of its own, the drum tracks in the lanes at the foot, the chord on each beat named above, and at the right each track&#39;s chains and settings, as the details view shows them. It opens on the patterns as written, before any generator, groove or register changes them, with a purple border.</p><p><img src="'+n+'" alt="Scene View of the intro of edm_density, as written"></p><p><code>V</code> switches to the notes as played, after every chain, groove, strum, shape and register, with a blue border, so that the two can be compared; a song without a seed shows one take of its random parts. The arrows move the cursor, and the line under the roll names the notes under it. <code>PgUp</code> and <code>PgDn</code> jump a bar, <code>-</code> and <code>=</code> make each step narrower or wider, and <code>[</code> and <code>]</code> scroll the tracks at the right. <code>P</code> or <code>Esc</code> closes it.</p><p><img src="'+i+'" alt="Scene View of the same scene, as played"></p>',23)])])}const f=t(h,[["render",l]]);export{b as __pageData,f as default};
